INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(40861, 'Jeremiah 30:11', 'Jeremiah', 30, 11, 'نو مالِک خُدائ فرمائى چې، زۀ ستا مل يم او زۀ به تا بچ کړم. او زۀ به هغه ټول قومونه مکمل تباه کړم چرته چې ما تاسو خوارۀ وارۀ کړى وئ، خو زۀ به تاسو په مکمل توګه نۀ تباه کوم. زۀ به تاسو په اِنصاف سره تنبيه کړم، او زۀ به تاسو هم داسې بې‌سزا نۀ پرېږدم.', 'نو مالک خدای فرمایی چې، زۀ ستا مل یم او زۀ به تا بچ کرم. او زۀ به هغه تول قومونه مکمل تباه کرم چرته چې ما تاسو خوارۀ وارۀ کری وی، خو زۀ به تاسو په مکمل توګه نۀ تباه کوم. زۀ به تاسو په انصاف سره تنبیه کرم، او زۀ به تاسو هم داسې بې‌سزا نۀ پرېزدم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_30_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40862, 'Jeremiah 30:12', 'Jeremiah', 30, 12, 'مالِک خُدائ داسې فرمائى چې، ستاسو زخمونه خطرناک دى، او ستاسو زخمونه لاعلاجه دى.', 'مالک خدای داسې فرمایی چې، ستاسو زخمونه خطرناک دی، او ستاسو زخمونه لاعلاجه دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_30_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40863, 'Jeremiah 30:13', 'Jeremiah', 30, 13, 'داسې څوک نشته چې ستا خيال وساتى، ستا د زخمونو دپاره دارو نشته، ستا دپاره علاج نشته دے.', 'داسې چوک نشته چې ستا خیال وساتی، ستا د زخمونو دپاره دارو نشته، ستا دپاره علاج نشته دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_30_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40864, 'Jeremiah 30:14', 'Jeremiah', 30, 14, 'ستا ټولو ملګرو تۀ هېر کړے يې، هغوئ ستا پرواه نۀ کوى. ما په تا باندې داسې حمله وکړه لکه څنګه چې په دشمن کوم، او د يو ظالم په شان مې سزا درکړه، ځکه چې ستا شرارتونه ډېر غټ دى، او ستا ګناهونه ډېر زيات دى.', 'ستا تولو ملګرو تۀ هېر کرے یې، هغوی ستا پرواه نۀ کوی. ما په تا باندې داسې حمله وکره لکه چنګه چې په دشمن کوم، او د یو ظالم په شان مې سزا درکره، جکه چې ستا شرارتونه دېر غت دی، او ستا ګناهونه دېر زیات دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_30_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40865, 'Jeremiah 30:15', 'Jeremiah', 30, 15, 'نو بيا ولې تاسو په خپلو زخمونو او درد ژړا فرياد کوئ، او تاسو وايئ چې د دې خو هيڅ علاج نشته؟ خو دا ما ستاسو د لويو شرارتونو او ډېرو ګناهونو په وجه درسره وکړل.', 'نو بیا ولې تاسو په خپلو زخمونو او درد ژرا فریاد کوی، او تاسو وایی چې د دې خو هیچ علاج نشته؟ خو دا ما ستاسو د لویو شرارتونو او دېرو ګناهونو په وجه درسره وکرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_30_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40866, 'Jeremiah 30:16', 'Jeremiah', 30, 16, 'خو هر هغه څوک چې تاسو روغ تېروى هغوئ به روغ تېر کړے شى، او ستاسو ټول دشمنان به جلاوطن کړے شى. هر هغه څوک چې تاسو لوټ کوى هغوئ به لوټ کړے شى، او څوک چې په تاسو باندې حمله کوى په هغوئ باندې به حمله وکړے شى.', 'خو هر هغه چوک چې تاسو روغ تېروی هغوی به روغ تېر کرے شی، او ستاسو تول دشمنان به جلاوطن کرے شی. هر هغه چوک چې تاسو لوت کوی هغوی به لوت کرے شی، او چوک چې په تاسو باندې حمله کوی په هغوی باندې به حمله وکرے شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_30_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40867, 'Jeremiah 30:17', 'Jeremiah', 30, 17, 'مالِک خُدائ فرمائى چې، زۀ به ستاسو صحت دوباره ښۀ کړم، او ستاسو زخمونو ته به شفا ورکړم. زۀ به دا کار وکړم ځکه چې ما اورېدلى دى چې خلق تا ته ”جلاوطن شوے“ وائى، ”صيون د چا چې څوک هم خيال نۀ ساتى.“', 'مالک خدای فرمایی چې، زۀ به ستاسو صحت دوباره شۀ کرم، او ستاسو زخمونو ته به شفا ورکرم. زۀ به دا کار وکرم جکه چې ما اورېدلی دی چې خلق تا ته ”جلاوطن شوے“ وایی، ”صیون د چا چې چوک هم خیال نۀ ساتی.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_30_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40868, 'Jeremiah 30:18', 'Jeremiah', 30, 18, 'مالِک خُدائ فرمائى چې، زۀ به د يعقوب اولاد د غلامۍ نه واپس راولم او په هغوئ به رحم وکړم، د يروشلم تباه شوے ښار به هم هغه ځائ کښې دوباره آباد کړم، او زوړ محل به يې په خپل اصلى ځائ کښې ودروم.', 'مالک خدای فرمایی چې، زۀ به د یعقوب اولاد د غلامی نه واپس راولم او په هغوی به رحم وکرم، د یروشلم تباه شوے شار به هم هغه جای کشې دوباره اباد کرم، او زور محل به یې په خپل اصلی جای کشې ودروم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_30_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40869, 'Jeremiah 30:19', 'Jeremiah', 30, 19, 'نو په هغه وخت کښې به د هغه خلقو نه د شُکر ګزارۍ حمدونه او د خوشحالۍ آوازونه واورېدلے شى. زۀ به د هغوئ شمېر زيات کړم، او هغوئ به کمولے نۀ شى. زۀ به خلق مجبور کړم چې د هغوئ عزت وکړى، او هغوئ به سپک نۀ شمېرلے کيږى.', 'نو په هغه وخت کشې به د هغه خلقو نه د شکر ګزاری حمدونه او د خوشحالی اوازونه واورېدلے شی. زۀ به د هغوی شمېر زیات کرم، او هغوی به کمولے نۀ شی. زۀ به خلق مجبور کرم چې د هغوی عزت وکری، او هغوی به سپک نۀ شمېرلے کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_30_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40870, 'Jeremiah 30:20', 'Jeremiah', 30, 20, 'د هغوئ ماشومان به لکه د پخوا په شان ژوند کوى، او د هغوئ جماعت به زما په مخکښې قائم شى، او زۀ به هغه ټولو خلقو له سزا ورکړم څوک چې په دوئ باندې ظلم کوى.', 'د هغوی ماشومان به لکه د پخوا په شان ژوند کوی، او د هغوی جماعت به زما په مخکشې قایم شی، او زۀ به هغه تولو خلقو له سزا ورکرم چوک چې په دوی باندې ظلم کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_30_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40871, 'Jeremiah 30:21', 'Jeremiah', 30, 21, 'د هغوئ مشر به د هغوئ د خپل قوم نه وى، او د هغوئ مشر به د هغوئ د خپلو خلقو نه وى. زۀ به هغه خپل ځان ته نزدې کړم او هغه به ما له راشى، ځکه چې څوک دا جرأت کولے شى چې نابللے راشى؟ دا د مالِک خُدائ فرمان دے.', 'د هغوی مشر به د هغوی د خپل قوم نه وی، او د هغوی مشر به د هغوی د خپلو خلقو نه وی. زۀ به هغه خپل جان ته نزدې کرم او هغه به ما له راشی، جکه چې چوک دا جرات کولے شی چې نابللے راشی؟ دا د مالک خدای فرمان دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_30_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40872, 'Jeremiah 30:22', 'Jeremiah', 30, 22, 'نو هغه وخت به تاسو زما خلق يئ او زۀ به ستاسو خُدائ پاک يم.“', 'نو هغه وخت به تاسو زما خلق یی او زۀ به ستاسو خدای پاک یم.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_30_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40873, 'Jeremiah 30:23', 'Jeremiah', 30, 23, 'ګورئ د مالِک خُدائ غصه لکه د طوفان په شان رانازليږى، او د تېزو هواګانو په شان د بدعمله خلقو په سر په غضب سره لګيږى.', 'ګوری د مالک خدای غصه لکه د طوفان په شان رانازلیزی، او د تېزو هواګانو په شان د بدعمله خلقو په سر په غضب سره لګیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_30_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40874, 'Jeremiah 30:24', 'Jeremiah', 30, 24, 'او د مالِک خُدائ سخت قهر او غضب به تر هغې پورې وى او واپس به نۀ شى ترڅو چې د هغۀ مقصد پوره شوے نۀ وى. په راتلونکو ورځو کښې به تاسو په دې هر څۀ باندې پوهه شئ.', 'او د مالک خدای سخت قهر او غضب به تر هغې پورې وی او واپس به نۀ شی ترچو چې د هغۀ مقصد پوره شوے نۀ وی. په راتلونکو ورجو کشې به تاسو په دې هر چۀ باندې پوهه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Jeremiah_30_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40875, 'Deuteronomy 12:1', 'Deuteronomy', 12, 1, 'کله چې تاسو هغې خاورې ته ورننوځئ چې ستاسو د نیکونو څښتن خدای تاسو ته درکړې ده، نو ترڅو پورې چې ژوندي یئ په دې قوانینو باندې باید عمل وکړئ.', 'کله چې تاسو هغې خاورې ته ورننوجی چې ستاسو د نیکونو چشتن خدای تاسو ته درکرې ده، نو ترچو پورې چې ژوندی یی په دې قوانینو باندې باید عمل وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_12_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40876, 'Deuteronomy 12:2', 'Deuteronomy', 12, 2, 'خو هغه قومونه چې هلته اوسیږي د نورو خدایانو عبادت کوي. نو کله چې تاسو هغه خاوره ونیوله باید د هغوی د عبادت ځایونه په پوره توګه وران کړئ یعنې هغه ځایونه چې په غرونو او په غونډیو باندې دي او یا د شنو ونو لاندې دي.', 'خو هغه قومونه چې هلته اوسیزی د نورو خدایانو عبادت کوی. نو کله چې تاسو هغه خاوره ونیوله باید د هغوی د عبادت جایونه په پوره توګه وران کری یعنې هغه جایونه چې په غرونو او په غوندیو باندې دی او یا د شنو ونو لاندې دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_12_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40877, 'Deuteronomy 12:3', 'Deuteronomy', 12, 3, 'د هغوی د قربانۍ ځایونه راوغورځوئ او هغه لویې تیږې چې د هغوی د عبادت دپاره ورڅخه کار اخیستل کیږي، ټوټې ټوټې کړئ. د هغوی د اشیره بتان وسوځوئ او نور بتان یې راچپه کړئ، ترڅو بیا هېڅکله په هغو ځایونو کې د هغو بتانو عبادت ونه شي.', 'د هغوی د قربانی جایونه راوغورجوی او هغه لویې تیزې چې د هغوی د عبادت دپاره ورچخه کار اخیستل کیزی، توتې توتې کری. د هغوی د اشیره بتان وسوجوی او نور بتان یې راچپه کری، ترچو بیا هېچکله په هغو جایونو کې د هغو بتانو عبادت ونه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_12_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40878, 'Deuteronomy 12:4', 'Deuteronomy', 12, 4, 'د خپل څښتن خدای عبادت په داسې ډول مه کوئ لکه څنګه چې دا خلک د خپلو خدایانو عبادت کوي.', 'د خپل چشتن خدای عبادت په داسې دول مه کوی لکه چنګه چې دا خلک د خپلو خدایانو عبادت کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_12_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40879, 'Deuteronomy 12:5', 'Deuteronomy', 12, 5, 'ستاسو د ټولو قبیلو د سیمو څخه به څښتن یو ځای غوره کړي او هلته باید تاسو د هغه حضور ته راشئ او د هغه عبادت وکړئ.', 'ستاسو د تولو قبیلو د سیمو چخه به چشتن یو جای غوره کری او هلته باید تاسو د هغه حضور ته راشی او د هغه عبادت وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_12_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40880, 'Deuteronomy 12:6', 'Deuteronomy', 12, 6, 'تاسو باید هلته خپلې سوځېدونکې نذرانې او نورې قربانۍ، خپل عشرونه او هدیې، هغه سوغاتونه چې د نذر په توګه یې څښتن ته ورکوئ، د خپلې خوښې نذرانې او د خپلو پادو او رمو لومړني زېږېدلي بچیان وړاندې کړئ.', 'تاسو باید هلته خپلې سوجېدونکې نذرانې او نورې قربانی، خپل عشرونه او هدیې، هغه سوغاتونه چې د نذر په توګه یې چشتن ته ورکوی، د خپلې خوشې نذرانې او د خپلو پادو او رمو لومرنی زېزېدلی بچیان وراندې کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_12_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40881, 'Deuteronomy 12:7', 'Deuteronomy', 12, 7, 'تاسو او ستاسو کورنۍ او نوکران به هلته د خپل څښتن خدای په حضور کې چې برکت یې درکړی دی خوراک کوئ او د هغو ښو شیانو دپاره به خوشحالي کوئ چې تاسو د هغو دپاره کار کړی دی.', 'تاسو او ستاسو کورنی او نوکران به هلته د خپل چشتن خدای په حضور کې چې برکت یې درکری دی خوراک کوی او د هغو شو شیانو دپاره به خوشحالی کوی چې تاسو د هغو دپاره کار کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_12_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
